extension ContinuumClientTypes {

    /// Whether this issue has any evidence (formerly 'artifacts') attached. NONE = no evidence; AVAILABLE = at least one evidence item exists -- call ListCodeIssueArtifacts to retrieve.
    public enum IssueEvidenceAvailability: Swift.Sendable, Swift.Equatable, Swift.RawRepresentable, Swift.CaseIterable, Swift.Hashable {
        case available
        case `none`
        case sdkUnknown(Swift.String)

        public static var allCases: [IssueEvidenceAvailability] {
            return [
                .available,
                .none
            ]
        }

        public init?(rawValue: Swift.String) {
            let value = Self.allCases.first(where: { $0.rawValue == rawValue })
            self = value ?? Self.sdkUnknown(rawValue)
        }

        public var rawValue: Swift.String {
            switch self {
            case .available: return "AVAILABLE"
            case .none: return "NONE"
            case let .sdkUnknown(s): return s
            }
        }
    }
}

